instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_details {\n	display: flex;\n	flex-wrap: wrap;\n	gap: 24px 32px;\n	margin-top: 8px;\n}\n\n/* Individual detail items */\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_detail {\n	display: flex;\n	align-items: baseline;\n	gap: 6px;\n}\n\n/* Labels styling - BOLD */\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_label {\n	font-weight: 700;\n	color: #263145;\n	font-size: 14px;\n	white-space: nowrap;\n}\n\n/* Values styling - NORMAL */\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_value {\n	font-weight: 400;\n	color: #4b5563;\n	font-size: 14px;\n	line-height: 1.5;\n}\n\n/* Responsive design for list layout */\n@media (max-width: 768px) {\n	.stm_lms_instructors__archive_wrapper {\n		flex-direction: column;\n	}\n	\n	.stm_lms_instructors__filter_wrapper {\n		width: 100%;\n		margin: 0 0 20px 0;\n	}\n	\n	.stm_lms_instructors__archive {\n		width: 100%;\n		margin-top: 20px;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructors__single {\n		flex-direction: column;\n		padding: 20px 16px;\n		text-align: left;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_user_side {\n		flex-direction: column;\n		text-align: left;\n		align-items: flex-start;\n		gap: 16px;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm-lms-user_avatar {\n		width: 60px;\n		height: 60px;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_info {\n		align-items: flex-start;\n		width: 100%;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_teaching,\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_description,\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_details {\n		flex-direction: column;\n		align-items: flex-start;\n		gap: 8px;\n	}\n	\n	.stm_l