t.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_detail {\\n\\t\\tflex-direction: row;\\n\\t}\\n}\\n\\n/* Responsive - Mobile */\\n@media (max-width: 767px) {\\n\\t.stm_lms_instructors_wrapper {\\n\\t\\tmargin: 0 0 20px;\\n\\t\\tpadding: 0;\\n\\t}\\n\\n\\t.stm_lms_instructors__archive_wrapper {\\n\\t\\tgap: 15px;\\n\\t}\\n\\n\\t.stm_lms_instructors__filter {\\n\\t\\tborder-radius: 0;\\n\\t\\tborder-left: none;\\n\\t\\tborder-right: none;\\n\\t}\\n\\n\\t.stm_lms_instructors__filter_form {\\n\\t\\tpadding: 15px;\\n\\t}\\n\\n\\t.stm_lms_instructors__filter_options {\\n\\t\\tmax-height: 400px;\\n\\t}\\n\\n\\t.stm_lms_instructors__filter_options_item {\\n\\t\\tmargin-bottom: 15px;\\n\\t\\tpadding-bottom: 10px;\\n\\t}\\n\\n\\t.stm_lms_instructors__filter_actions {\\n\\t\\tflex-direction: column;\\n\\t}\\n\\n\\t.stm_lms_instructors__filter_actions_button,\\n\\t.stm_lms_instructors__filter_actions_reset {\\n\\t\\twidth: 100%;\\n\\t}\\n\\n\\t.stm_lms_instructors__archive {\\n\\t\\twidth: 100%;\\n\\t\\tmax-width: 100%;\\n\\t\\tflex: 1;\\n\\t}\\n}\\n\\n/* Ensure no horizontal overflow */\\n.stm_lms_instructors_wrapper,\\n.stm_lms_instructors__archive_wrapper,\\n.stm_lms_instructors__filter_wrapper,\\n.stm_lms_instructors__archive,\\n.stm_lms_instructors__grid {\\n\\toverflow-x: hidden;\\n\\tbox-sizing: border-box;\\n}\\n\\n/* Ensure proper spacing and alignment */\\n.stm_lms_instructors__grid .stm_lms_instructors__single {\\n\\ttext-decoration: none;\\n\\ttransition: all 0.3s ease;\\n}\\n\\n.stm_lms_instructors__grid .stm_lms_instructors__single:hover {\\n\\ttext-decoration: none;\\n}\\n\\n\\n\\n\\n\\n\\n.ehf-header #masthead {\\n    z-index: 999999999;\\n    box-shadow: 0px 3px 10px 1px #3333;\\n}\\n.stm_lms_instructors__archive .stm_lms_instructors__grid {\\n    justify-content: normal;\\n    gap: 12px;\\n}\\n.acf-tab-wrap.-top {\\n    display: none;\\n}\\n\\n.mkh-teacher-profile-form input[type=\\\"number\\\"]{\\n\\t    padding: 4.5px 15px !important;\\n\\t    border: #7e8993 solid 1px !important;\\n}\\ninput#acf-field_mkh_teacher_profile_sect {\\n    padding: 8px 15px;\\n}\\n.mkh-teacher-profile-form .acf-form {\\n    background: #273044 !important;\\n}\\n.mkh-teacher-profile-form .acf-button {\\n    background:  #273044 !important;\\n}\\ninput.stm-lms-btn.stm-lms-btn_primary {\\n    background: var(--accent-100);\\n}\\n.mkh-teacher-profile-form select,.mkh-teacher-profile-form input[type=\\\"url\\\"]{\\n    padding: 5px 15px !important;\\n}\\ninput#acf-field_mkh_teacher_profile_hourly_rate {\\n    width: 75px;\\n}\\n.acf-url i {\\n    top: 8px;\\n}\\nbody.mkh-showing-about .masterstudy-tabs__item:not(#mkh-about-teacher-tab) {\\n    background: #f5f5f5 !important;\\n    color: #273044 !important;\\n    padding: 25px 40px;\\n    border-radius: 50px;\\n}\\nbutton#mkh-about-teacher-tab,.masterstudy-tabs.masterstudy-tabs_style-buttons .masterstudy-tabs__item.masterstudy-tabs__item_active{\\n    border-radius: 50px;\\n    width: auto;\\n    padding: 15px 40px !important;\\n}\\nli.masterstudy-tabs__item.masterstudy-tabs__item_active {\\n    height: 48px;\\n    background: #273044 !important;\\n    color: #fff !important;\\n}\\n.mkh-teacher-profile-column {\\n    padding: 12px;\\n    background: #f0f0f0;\\n}\\n.mkh-teacher-profile-timeline {\\n    padding-left: 0 !important;\\n}\\n.mkh-teacher-profile-label {\\n    font-size: 15px;\\n}\\n.stm_lms_instructors__filter_options_item_checkbox_inner span{\\n\\tbackground-color: #d5d5d5;\\n    border-style: none;\\n}\\n/*\\n.mkh-teacher-profile-timeline-item {\\n    margin-bottom: 0 !important;\\n}\\n.mkh-accordion {\\n   \\n    padding-bottom: 0 !important;\\n}\\n*/\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-13 06:00:49\"\n    }\n}',	'',	'',	'trash',	'closed',	'closed',	'',	'553e9ab9-b505-4bd1-845b-13e77b3ea6b8',	'',	'',	'2026-08-13 06:00:49',	'2026-08-13 06:00:49',	'',	0,	'https://muslimkidstime.local/5