er: #7e8993 solid 1px !important;\\n}\\ninput#acf-field_mkh_teacher_profile_sect {\\n    padding: 8px 15px;\\n}\\n.mkh-teacher-profile-form .acf-form {\\n    background: #273044 !important;\\n}\\n.mkh-teacher-profile-form .acf-button {\\n    background:  #273044 !important;\\n}\\ninput.stm-lms-btn.stm-lms-btn_primary {\\n    background: var(--accent-100);\\n}\\n.mkh-teacher-profile-form select,.mkh-teacher-profile-form input[type=\\\"url\\\"]{\\n    padding: 5px 15px !important;\\n}\\ninput#acf-field_mkh_teacher_profile_hourly_rate {\\n    width: 75px;\\n}\\n.acf-url i {\\n    top: 8px;\\n}\\nbody.mkh-showing-about .masterstudy-tabs__item:not(#mkh-about-teacher-tab) {\\n    background: #f5f5f5 !important;\\n    color: #273044 !important;\\n    padding: 25px 40px;\\n    border-radius: 50px;\\n}\\nbutton#mkh-about-teacher-tab,.masterstudy-tabs.masterstudy-tabs_style-buttons .masterstudy-tabs__item.masterstudy-tabs__item_active{\\n    border-radius: 50px;\\n    width: auto;\\n    padding: 15px 40px !important;\\n}\\nli.masterstudy-tabs__item.masterstudy-tabs__item_active {\\n    height: 48px;\\n    background: #273044 !important;\\n    color: #fff !important;\\n}\\n.mkh-teacher-profile-column {\\n    padding: 12px;\\n    background: #f0f0f0;\\n}\\n.mkh-teacher-profile-timeline {\\n    padding-left: 0 !important;\\n}\\n.mkh-teacher-profile-label {\\n    font-size: 15px;\\n}\\n.stm_lms_instructors__filter_options_item_checkbox_inner span{\\n\\tbackground-color: #d5d5d5;\\n    border-style: none;\\n}\\n/*\\n.mkh-teacher-profile-timeline-item {\\n    margin-bottom: 0 !important;\\n}\\n.mkh-accordion {\\n   \\n    padding-bottom: 0 !important;\\n}\\n*/\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-08-13 06:01:15\"\n    }\n}',	'',	'',	'trash',	'closed',	'closed',	'',	'9f158182-fe44-4650-8a0a-a58fcb5f26c2',	'',	'',	'2026-08-13 06:01:15',	'2026-08-13 06:01:15',	'',	0,	'https://muslimkidstime.local/9f158182-fe44-4650-8a