(53723,	1,	'2026-08-13 06:30:45',	'2026-08-13 06:30:45',	'/**\n * Instructors Filter Styles\n * \n * Based on courses filter styles for consistency\n * \n * @package MS_LMS_Starter_Theme\n */\n\n/* Main wrapper layout - matching Courses Archive structure */\n\n.button-template, .button-template-outline, .comment-respond input[type=button], .comment-respond input[type=submit], .starter-button, .starter-button-outline, .wp-block-button .wp-block-button__link, .wp-block-button.is-style-outline .wp-block-button__link, .wp-block-search__button, a.starter-button, a.starter-button-outline, button, input[type=button], input[type=submit] {\n\n    background-color: #00255B;\n}\n\n.stm_lms_instructors__filter_actions {\n    display: flex;\n    gap: 12px;\n    margin-top: 10px;\n    padding: 20px 12px 0;\n    border-top: 0;\n    margin-bottom: 10px;\n}\n.stm_lms_instructors__filter_form {\n    padding: 0 0px 20px !important;\n}\n\n.stm_lms_instructors__filter_wrapper {\n    margin: 0px 20px 20px 0 !important;\n}\n.stm_lms_instructors__filter_options_item:first-child {\n    border-top: 3px solid #00255B !important;\n}\n.stm_lms_instructors__grid .stm_lms_instructors__single:hover {\n    transform: translateY(0px);\n}\n.stm_lms_instructors__archive .stm_lms_instructors__grid\n {\n    gap: 24px !important;\n}\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructors__single:hover {\n    box-shadow: 0 1px 6px 2.2px rgba(0, 0, 0, .15) !important;\n}\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructors__single .stm_lms_user_side\n {\n    max-width: 100%;\n    padding: 0;\n    margin: 0 auto;\n}\n.stm_lms_instructors_wrapper {\n	margin-top: 55px;\n	margin-bottom: 30px;\n}\n\n.stm_lms_instructors__archive_wrapper {\n	display: flex;\n	margin: 0 0 50px;\n}\n\n.stm_lms_instructors__archive {\n	width: calc(100% - 300px);\n	margin-top: 55px;\n	flex-grow: 1;\n}\n\n/* Filter sidebar - matching Courses Archive filter styling */\n.stm_lms_instructors__filter_wrapper {\n	width: 280px;\n	margin: 28px 20px 20px 0;\n	flex-shrink: 0;\n}\n\n.stm_lms_instructors__filter {\n	background: #fff;\n	border: 1px solid #eef0f2;\n	border-radius: 8px;\n	overflow: hidden;\n	box-shadow: 0 2px 5px 0 rgba(0,0,0,.18), inset 0 3px 0 0 rgba(25,94,200,.004);\n}\n\n.stm_lms_instructors__filter_toggle {\n	display: none;\n	padding: 15px 20px;\n	background: #f9f9f9;\n	border-bottom: 1px solid #eef0f2;\n	color: #263145;\n	font-weight: 600;\n	text-decoration: none;\n}\n\n.stm_lms_instructors__filter_form {\n	padding: 20px;\n}\n\n\n/* Filter items - matching Courses Archive filter structure */\n.stm_lms_instructors__filter_options_item {\n	border-top: 1px solid #e0e0e0;\n}\n\n.stm_lms_instructors__filter_options_item:first-child {\n	border-top: 3px solid #385bce;\n}\n\n.stm_lms_instructors__filter_options_item_title {\n	position: relative;\n	padding: 21px 60px 21px 25px;\n	cursor: pointer;\n}\n\n.stm_lms_instructors__filter_options_item_title h3 {\n	margin: 0;\n	font-size: 16px;\n	color: #232628;\n	font-weight: 600;\n	letter-spacing: 0;\n}\n\n.stm_lms_instructors__filter_options_item_title_toggler {\n	position: absolute;\n	right: 25px;\n	top: 50%;\n	height: 20px;\n	width: 20px;\n	margin: -10px 0 0;\n}\n\n.stm_lms_instructors__filter_options_item_title_toggler:after {\n	content: \"\";\n	display: block;\n	position: absolute;\n	top: 50%;\n	left: 0;\n	margin-top: -1px;\n	width: 100%;\n	height: 2px;\n	background-color: #385bce;\n	transition: .3s ease;\n}\n\n.stm_lms_instructors__filter_options_item_title_toggler:before {\n	content: \"\";\n	display: block;\n	position: absolute;\n	top: 0;\n	left: 50%;\n	margin-left: -1px;\n	width: 2px;\n	height: 100%;\n	background-color: #385bce;\n	transition: .3s ease;\n	opacity: 1;\n}\n\n.stm_lms_instructors__filter_options_item.active .stm_lms_instructors__filter_options_item_title_toggler:after {\n	background-color: #9397a1;\n}\n\n.stm_lms_instructors__filter_options_item.active .stm_lms_instructors__filter_options_item_title_toggler:before {\n	opacity: 0;\n}\n\n.stm_lms_instructors__filter_options_item_content {\n	padding: 0 25px 25px;\n	display: block;\n}\n\n.stm_lms_instructors__filter_options_item.collapsed .stm_lms_instructors__filter_options_item_content {\n	display: none;\n}\n\n/* Checkbox styles - matching Courses Archive */\n.stm_lms_instructors__filter_options_item_checkbox {\n	margin: 0 0 10px;\n	vertical-align: top;\n	cursor: pointer;\n}\n\n.stm_lms_instructors__filter_options_item_checkbox:last-child {\n	margin-bottom: 0;\n}\n\n.stm_lms_instructors__filter_options_item_checkbox_inner {\n	position: relative;\n	top: 0;\n	border: 0;\n	width: 18px;\n	height: 18px;\n	border-radius: 3px;\n	overflow: hidden;\n	display: inline-block;\n	margin-right: 10px;\n}\n\n.stm_lms_instructors__filter_options_item_checkbox_inner input {\n	position: absolute;\n	width: 100%;\n	height: 100%;\n	opacity: 0;\n	cursor: pointer;\n	z-index: 2;\n}\n\n.stm_lms_instructors__filter_options_item_checkbox_inner span {\n	display: flex;\n	align-items: center;\n	justify-content: center;\n	width: 18px;\n	height: 18px;\n	border: 2px solid #dfe1e5;\n	border-radius: 3px;\n	background: #fff;\n	transition: all 0.2s ease;\n}\n\n.stm_lms_instructors__filter_options_item_checkbox_inner input:checked + span {\n	background: #385bce;\n	border-color: #385bce;\n}\n\n.stm_lms_instructors__filter_options_item_checkbox_inner span i {\n	color: #fff;\n	font-size: 12px;\n	display: none;\n}\n\n.stm_lms_instructors__filter_options_item_checkbox_inner input:checked + span i {\n	display: block;\n}\n\n.stm_lms_instructors__filter_options_item_checkbox_label {\n	font-size: 14px;\n	color: #263145;\n	line-height: 1.4;\n}\n\n/* Radio styles */\n.stm_lms_instructors__filter_options_item_radio {\n	display: flex;\n	align-items: center;\n	margin-right: 10px;\n}\n\n.stm_lms_instructors__filter_options_item_radio_inner {\n	position: relative;\n	width: 18px;\n	height: 18px;\n}\n\n.stm_lms_instructors__filter_options_item_radio_inner input {\n	position: absolute;\n	width: 100%;\n	height: 100%;\n	opacity: 0;\n	cursor: pointer;\n	z-index: 2;\n}\n\n.stm_lms_instructors__filter_options_item_radio_fake {\n	display: flex;\n	align-items: center;\n	justify-content: center;\n	width: 18px;\n	height: 18px;\n	border: 2px solid #dfe1e5;\n	border-radius: 50%;\n	background: #fff;\n	transition: all 0.2s ease;\n}\n\n.stm_lms_instructors__filter_options_item_radio_inner input:checked + .stm_lms_instructors__filter_options_item_radio_fake {\n	background: #385bce;\n	border-color: #385bce;\n}\n\n.stm_lms_instructors__filter_options_item_radio_inner input:checked + .stm_lms_instructors__filter_options_item_radio_fake:before {\n	content: \'\';\n	width: 8px;\n	height: 8px;\n	background: #fff;\n	border-radius: 50%;\n}\n\n.stm_lms_instructors__filter_options_item_radio_label {\n	font-size: 14px;\n	color: #263145;\n	line-height: 1.4;\n}\n\n/* Price range inputs */\n.stm_lms_instructors__filter_options_item_price_inputs {\n	display: flex;\n	gap: 10px;\n}\n\n.stm_lms_instructors__filter_options_item_price_input {\n	flex: 1;\n}\n\n.stm_lms_instructors__filter_options_item_price_input label {\n	display: block;\n	font-size: 12px;\n	color: #6b7280;\n	margin-bottom: 5px;\n}\n\n.stm_lms_instructors__filter_options_item_price_input input {\n	width: 100%;\n	padding: 8px 12px;\n	border: 1px solid #dfe1e5;\n	border-radius: 4px;\n	font-size: 14px;\n	color: #263145;\n	transition: border-color 0.2s ease;\n}\n\n.stm_lms_instructors__filter_options_item_price_input input:focus {\n	outline: none;\n	border-color: #385bce;\n}\n\n/* Filter actions */\n.stm_lms_instructors__filter_actions {\n	display: flex;\n	gap: 15px;\n	margin-top: 20px;\n	padding-top: 20px;\n	border-top: 1px solid #eef0f2;\n}\n\n.stm_lms_instructors__filter_actions_button {\n	flex: 1;\n	padding: 12px 20px;\n	background: #385bce;\n	color: #fff;\n	border: none;\n	border-radius: 4px;\n	font-size: 14px;\n	font-weight: 600;\n	cursor: pointer;\n	transition: background 0.2s ease;\n}\n\n.stm_lms_instructors__filter_actions_button:hover {\n	background: #2a4494;\n}\n\n.stm_lms_instructors__filter_actions_reset {\n	display: flex;\n	align-items: center;\n	gap: 5px;\n	padding: 12px 20px;\n	background: #f9f9f9;\n	color: #263145;\n	border: 1px solid #dfe1e5;\n	border-radius: 4px;\n	font-size: 14px;\n	text-decoration: none;\n	transition: all 0.2s ease;\n}\n\n.stm_lms_instructors__filter_actions_reset:hover {\n	background: #eef0f2;\n	border-color: #c4c6c9;\n}\n\n.stm_lms_instructors__filter_actions_reset i {\n	font-size: 16px;\n}\n\n/* Content area - matching Courses Archive structure */\n.stm_lms_instructors__archive {\n	margin: 0;\n}\n\n/* Convert grid to list layout */\n.stm_lms_instructors__archive .stm_lms_instructors__grid {\n	display: flex;\n	flex-direction: column;\n	gap: 0;\n	margin: 0 0 50px;\n	padding: 0;\n	width: 100%;\n}\n\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructors__single {\n	display: flex;\n	align-items: flex-start;\n	width: 100%;\n	padding: 24px;\n	border-radius: 0;\n	border: none;\n	border-bottom: 1px solid #eef0f2;\n	background: #fff;\n	transition: background-color 0.2s ease;\n	text-decoration: none;\n}\n\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructors__single:first-child {\n	border-top: 1px solid #eef0f2;\n}\n\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructors__single:hover {\n	background-color: #f9f9f9;\n}\n\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_user_side {\n	display: flex;\n	align-items: flex-start;\n	gap: 20px;\n	width: 100%;\n}\n\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm-lms-user_avatar {\n	flex-shrink: 0;\n	width: 70px;\n	height: 70px;\n}\n\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm-lms-user_avatar img {\n	width: 100%;\n	height: 100%;\n	object-fit: cover;\n	border-radius: 50%;\n}\n\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_user_side h3 {\n	margin: 0 0 4px 0;\n	font-size: 20px;\n	font-weight: 700;\n	color: #232628;\n	line-height: 1.3;\n}\n\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_user_side h5 {\n	margin: 0 0 16px 0;\n	font-size: 14px;\n	font-weight: 400;\n	color: #6b7280;\n}\n\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm-lms-user_rating {\n	display: flex;\n	align-items: center;\n	gap: 10px;\n	margin-top: 12px;\n}\n\n/* Instructor info container for list layout */\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_info {\n	flex: 1;\n	display: flex;\n	flex-direction: column;\n	gap: 12px;\n	text-align: left;\n}\n\n/* Teaching skills section */\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_teaching {\n	display: flex;\n	flex-wrap: wrap;\n	gap: 6px;\n	align-items: baseline;\n	margin-bottom: 4px;\n}\n\n/* Description section */\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_description {\n	display: flex;\n	flex-direction: column;\n	gap: 4px;\n	margin-bottom: 8px;\n}\n\n/* Details container */\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_details {\n	display: flex;\n	flex-wrap: wrap;\n	gap: 24px 32px;\n	margin-top: 8px;\n}\n\n/* Individual detail items */\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_detail {\n	display: flex;\n	align-items: baseline;\n	gap: 6px;\n}\n\n/* Labels styling - BOLD */\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_label {\n	font-weight: 700;\n	color: #263145;\n	font-size: 14px;\n	white-space: nowrap;\n}\n\n/* Values styling - NORMAL */\n.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_value {\n	font-weight: 400;\n	color: #4b5563;\n	font-size: 14px;\n	line-height: 1.5;\n}\n\n/* Responsive design for list layout */\n@media (max-width: 768px) {\n	.stm_lms_instructors__archive_wrapper {\n		flex-direction: column;\n	}\n	\n	.stm_lms_instructors__filter_wrapper {\n		width: 100%;\n		margin: 0 0 20px 0;\n	}\n	\n	.stm_lms_instructors__archive {\n		width: 100%;\n		margin-top: 20px;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructors__single {\n		flex-direction: column;\n		padding: 20px 16px;\n		text-align: left;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_user_side {\n		flex-direction: column;\n		text-align: left;\n		align-items: flex-start;\n		gap: 16px;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm-lms-user_avatar {\n		width: 60px;\n		height: 60px;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_info {\n		align-items: flex-start;\n		width: 100%;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_teaching,\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_description,\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_details {\n		flex-direction: column;\n		align-items: flex-start;\n		gap: 8px;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_detail {\n		flex-direction: row;\n		gap: 6px;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm-lms-user_rating {\n		justify-content: flex-start;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_details {\n		gap: 12px 16px;\n	}\n}\n\n@media (max-width: 480px) {\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructors__single {\n		padding: 16px 12px;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm-lms-user_avatar {\n		width: 50px;\n		height: 50px;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_user_side h3 {\n		font-size: 18px;\n	}\n	\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .stm_lms_instructor_label,\n	.stm_lms_instructors__archive .stm_lms_instructors__grid .s